  private final ReceiveService.Listener receiveListener=(origin,event)->{
    if(isDestroyed())return;
    if(!origin.equals(receivedOrigin.isEmpty()?baseUrl:receivedOrigin)){if("saved".equals(event.optString("status"))){if("history".equals(screen))showHistory();else if(status!=null)status.setText("Đã lưu · "+event.optString("path"));}else if("error".equals(event.optString("status")))problem(event.optString("error","Chưa lưu được file."));return;}
    if("receive".equals(screen)&&received!=null&&received.optString("code").equals(event.optString("code"))){String id=event.optString("id"),state=event.optString("status");TextView label=receiveLabels.get(id);
      if(label!=null){label.setTextColor("error".equals(state)?RED:GREEN);label.setText("saved".equals(state)?"Đã lưu · "+event.optString("path"):"progress".equals(state)?"Đang lưu · "+formatSize(event.optLong("bytes"))+" / "+formatSize(event.optLong("total")):event.optString("error","Chưa lưu được. Bấm Lưu để thử lại."));}
      if("error".equals(state)&&status!=null)status.setText(event.optString("error","Chưa lưu được file."));
    }
    if("history".equals(screen)&&"saved".equals(event.optString("status")))showHistory();
  };
  private final HostService.Listener hostListener=new HostService.Listener(){
    @Override public void onReady(String name,String url){if(isFinishing()||isDestroyed())return;refreshHostButtons();if(hostPending){hostPending=false;connectionGeneration++;setConnecting(false);enterSession(url,name);}}
    @Override public void onFailure(String text){if(isFinishing()||isDestroyed())return;hostPending=false;refreshHostButtons();problem(text);}
    @Override public void onStopped(){if(isFinishing()||isDestroyed())return;hostPending=false;boolean local=baseUrl.startsWith("http://127.0.0.1:");unbindHost();if(local){baseUrl="";received=null;showConnect();problem("Phiên chia sẻ đã dừng.");}else refreshHostButtons();}
  };
  private final ServiceConnection hostConnection=new ServiceConnection(){
    @Override public void onServiceConnected(ComponentName name,IBinder binder){hostService=((HostService.LocalBinder)binder).getService();hostService.addListener(hostListener);refreshHostButtons();}
    @Override public void onServiceDisconnected(ComponentName name){hostService=null;hostPending=false;refreshHostButtons();}
  };
