  private void receiveShared(Intent incoming){
    if(!SharedFiles.accepts(incoming))return;
    try{
      ArrayList<Uri> uris=SharedFiles.collect(incoming);
      for(Uri uri:uris)if(checkUriPermission(uri,android.os.Process.myPid(),android.os.Process.myUid(),Intent.FLAG_GRANT_READ_URI_PERMISSION)!=android.content.pm.PackageManager.PERMISSION_GRANTED)throw new IOException("Chưa có quyền đọc file. Mở lại mục Chia sẻ từ ứng dụng nguồn.");
      if(SendService.busy()&&sendStarted){selected.clear();sendStarted=false;}
      for(Uri uri:uris)if(!pendingShared.contains(uri))pendingShared.add(uri);
      hostPending=false;showConnect();if(status!=null)status.setText("Đang đọc file chia sẻ… Sau đó chọn thiết bị nhận và bấm Gửi.");importPendingShares();
    }catch(Exception error){problem(error.getMessage());}
    finally{setIntent(new Intent(this,MainActivity.class).setAction(Intent.ACTION_MAIN));}
  }
  private void importPendingShares(){
    if(selecting||pendingShared.isEmpty()||isDestroyed())return;
    ArrayList<Uri> batch=new ArrayList<>(pendingShared);pendingShared.clear();selecting=true;
    work.execute(()->{ArrayList<JSONObject> found=new ArrayList<>();String error=null;for(Uri uri:batch)try{found.add(describe(uri));}catch(Exception failure){error=failure.getMessage();}final String message=error;
      main.post(()->{if(isDestroyed())return;selecting=false;HashSet<String> seen=new HashSet<>();for(JSONObject file:selected)seen.add(file.optString("uri"));for(JSONObject file:found)if(seen.add(file.optString("uri")))selected.add(file);
        if("send".equals(screen)){renderSelected();renderSendState(SendService.state());}else if("connect".equals(screen)&&status!=null)status.setText("Đã chọn "+selected.size()+" file. Chọn thiết bị nhận để xem và gửi.");
        if(message!=null)problem(message);importPendingShares();});
    });
  }
  private void checkOffers(){
    if(offerDialog||hostService==null||!hostService.isReady())return;
    try{JSONArray pending=hostService.pendingOffers();if(pending.length()==0)return;JSONObject item=pending.getJSONObject(0);offerDialog=true;
      AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Nhận file từ "+item.optString("name")).setMessage(item.optInt("count")+" file · "+formatSize(item.optLong("size"))+"\nFile sẽ lưu vào Album/FlowDrop hoặc Download/FlowDrop theo loại file.")
        .setNegativeButton("Từ chối",(d,w)->{try{hostService.answerOffer(item.optString("id"),false);}catch(Exception ignored){}})
        .setPositiveButton("Nhận và lưu",(d,w)->{try{if(!AppUpdates.reserveTransfer())throw new IOException("Đang cài cập nhật. Mở lại FlowDrop sau khi cài xong.");JSONObject accepted=hostService.answerOffer(item.optString("id"),true);askNotifications();startForegroundService(new Intent(this,ReceiveService.class).putExtra("origin",accepted.getString("origin")).putExtra("code",accepted.getString("code")).putExtra("sessionId",accepted.getString("id")));showSessions();}catch(Exception e){problem(e.getMessage());}}).setCancelable(false).create();
      dialog.setOnDismissListener(d->offerDialog=false);dialog.show();dialog.getButton(AlertDialog.BUTTON_POSITIVE).setFilterTouchesWhenObscured(true);
    }catch(Exception ignored){}
  }
  private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
