  private TextView label(String value,int size,int color,boolean heavy){TextView t=new TextView(this);t.setText(value);t.setTextColor(color);t.setTextSize(size);t.setTypeface(heavy?(bold!=null?bold:Typeface.DEFAULT_BOLD):(regular!=null?regular:Typeface.DEFAULT));t.setLineSpacing(dp(3),1);return t;}
